typedef unsigned long long big_int;

class string_buf
{
    big_int *data;
    int ref_count;
    int char_length;
    int block_length;
    int max_blocks;
public:
    inline int compare(const char *str) const
    {
        int i;
        const char *a = reinterpret_cast<const char *>(data);
        for (i = 0; i < char_length; i++) {
            if (str[i] == '\0') return -1;
            if (a[i] == str[i]) continue;
            if (str[i] > a[i]) return 1;
            if (str[i] < a[i]) return -1;
        }
        if (str[i] == '\0') return 0;
        return 1;
    }

    inline bool is_equal(const char *str) const
    {
        return compare(str) == 0;
    }
};

class stringx
{
    char *chars;
    string_buf *my_buf;
public:
    friend inline bool operator==(const stringx& lhs, const char *rhs);
};

inline bool operator==(const stringx& lhs, const char *rhs)
{
    return lhs.my_buf->is_equal(rhs);
}

class signaller
{
    unsigned int flags;
    void *signals;
public:
    virtual ~signaller();
};

class script_controller : public signaller
{
public:
    virtual ~script_controller();
    virtual void update();
};

class slc_controller_t
{
public:
    unsigned find_instance(const stringx& n) const;
};

extern script_controller* script_pad;

unsigned slc_controller_t::find_instance(const stringx& n) const
{
  if (n=="NULL") return (unsigned)0;
  if (n=="CONTROLLER_1") return (unsigned)&script_pad[0];
  if (n=="CONTROLLER_2") return (unsigned)&script_pad[1];

  return (unsigned)0;
}
